from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        # Use OrderedDict to maintain insertion order, which will represent LRU order
        # Keys are stored in the order they are accessed (most recent at the end)
        self.cache = OrderedDict()

    def get(self, key: int, default: int = -1) -> int:
        if key not in self.cache:
            return default
        # Move the accessed item to the end (most recently used)
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            # If key exists, update value and move to end
            self.cache[key] = value
            self.cache.move_to_end(key)
        else:
            if len(self.cache) >= self.capacity:
                # Evict the least recently used item (first item in OrderedDict)
                self.cache.popitem(last=False)
            self.cache[key] = value

    def __len__(self):
        return len(self.cache)

    def __contains__(self, key):
        return key in self.cache

    def keys(self):
        # Return keys in LRU order (oldest first)
        return list(self.cache.keys())
